#!/usr/bin/env python3
import json, os, pathlib, subprocess, urllib.parse, urllib.request
ROOT=pathlib.Path("/home/apr/eth-hedge-live")
ENV=ROOT/".env"
EXE=ROOT/"executor_bot.py"
ADM=ROOT/"executor_admin.py"
CFG=ROOT/"executor_config.json"
STATE=ROOT/"executor_state.json"
STOP=ROOT/"STOP_EXECUTION"
PY=ROOT/".venv/bin/python"

if not ENV.is_file() or not PY.is_file():
    raise SystemExit("missing dedicated env/venv")

vals={}
private=False
for line in ENV.read_text(errors="ignore").splitlines():
    s=line.strip()
    if not s or s.startswith("#") or "=" not in s:continue
    k,v=s.split("=",1);k=k.strip();v=v.strip().strip("'\"")
    if k in {"LIGHTER_BASE_URL","LIGHTER_ACCOUNT_INDEX","LIGHTER_API_KEY_INDEX"}:vals[k]=v
    elif k=="LIGHTER_API_PRIVATE_KEY_HEX":private=bool(v)
if vals.get("LIGHTER_ACCOUNT_INDEX")!="749122" or vals.get("LIGHTER_API_KEY_INDEX")!="45" or not private:
    raise SystemExit("identity/credential presence mismatch")
if ENV.stat().st_mode & 0o077:
    raise SystemExit("unsafe .env permissions")

url="https://mainnet.zklighter.elliot.ai/api/v1/account?"+urllib.parse.urlencode({"by":"index","value":"749122","active_only":"false"})
req=urllib.request.Request(url,headers={"User-Agent":"eth-hedge-executor-deploy/1.0"})
with urllib.request.urlopen(req,timeout=15) as r:j=json.load(r)
a=(j.get("accounts") or [{}])[0]
positions=[]
for p in a.get("positions") or []:
    try:q=float(p.get("position") or 0)
    except:q=0
    if abs(q)>1e-12:positions.append({"symbol":p.get("symbol"),"market_id":p.get("market_id"),"position":q,"sign":p.get("sign")})
if positions: raise SystemExit("refusing deploy: dedicated account not flat")
if float(a.get("collateral") or 0)<80: raise SystemExit("collateral below 80")

cfg={
  "version":1,"mode":"LOCKED","live_enabled":False,
  "account_index":749122,"api_key_index":45,"market_index":0,
  "entry_size_eth":0.1,"hard_max_short_eth":0.1,
  "allow_averaging":False,"spot_actions_allowed":False,
  "tp_pct":0.003,"entry_max_slippage":0.003,"tp_max_slippage":0.003,
  "rollback_max_slippage":0.005,"adverse_alert_pct":0.015,
  "hold_alert_minutes":60,"auto_stop_loss":False,"auto_timeout_exit":False,
  "max_signal_entry_lag_seconds":90,"min_collateral_usdc":80.0
}
CFG.write_text(json.dumps(cfg,ensure_ascii=False,indent=2)+"\n");os.chmod(CFG,0o600)
STOP.write_text("EXECUTION LOCKED after deploy\n");os.chmod(STOP,0o600)
EXE.write_text("#!/usr/bin/env python3\nfrom __future__ import annotations\nimport argparse, asyncio, fcntl, json, os, pathlib, time, urllib.parse, urllib.request\nfrom datetime import datetime, timezone\n\nROOT=pathlib.Path(\"/home/apr/eth-hedge-live\")\nENV=ROOT/\".env\"\nMONITOR_STATE=ROOT/\"state.json\"\nMONITOR_CONFIG=ROOT/\"config.json\"\nCONFIG=ROOT/\"executor_config.json\"\nSTATE=ROOT/\"executor_state.json\"\nLEDGER=ROOT/\"executor_ledger.jsonl\"\nLOG=ROOT/\"executor.log\"\nLOCK=ROOT/\"executor.lock\"\nSTOP=ROOT/\"STOP_EXECUTION\"\n\nACCOUNT_INDEX=749122\nAPI_KEY_INDEX=45\nMARKET_INDEX=0\nHARD_MAX_ETH=0.1\nBASE_SCALE=10000\nPRICE_SCALE=100\nBINANCE=\"https://fapi.binance.com/fapi/v1/ticker/price?symbol=ETHUSDT\"\n\ndef now_ms(): return int(time.time()*1000)\ndef iso(ms=None):\n    if ms is None: return datetime.now(timezone.utc).isoformat()\n    return datetime.fromtimestamp(ms/1000,tz=timezone.utc).isoformat()\n\ndef emit(event, **data):\n    row={\"event\":event,\"at\":iso(),**data}\n    line=json.dumps(row,ensure_ascii=False,separators=(\",\",\":\"))\n    with LEDGER.open(\"a\",encoding=\"utf-8\") as f: f.write(line+\"\\n\")\n    with LOG.open(\"a\",encoding=\"utf-8\") as f: f.write(line+\"\\n\")\n    print(line)\n\ndef load_env():\n    vals={}\n    for line in ENV.read_text(errors=\"ignore\").splitlines():\n        s=line.strip()\n        if not s or s.startswith(\"#\") or \"=\" not in s: continue\n        k,v=s.split(\"=\",1); vals[k.strip()]=v.strip().strip(\"'\\\"\")\n    return vals\n\ndef load_json(p, default=None):\n    if not p.exists(): return default\n    return json.loads(p.read_text())\n\ndef save_json(p,obj):\n    tmp=p.with_suffix(p.suffix+\".tmp\")\n    tmp.write_text(json.dumps(obj,ensure_ascii=False,indent=2)+\"\\n\",encoding=\"utf-8\")\n    os.replace(tmp,p)\n    os.chmod(p,0o600)\n\ndef default_state():\n    return {\n        \"version\":1,\n        \"last_attempted_signal_close_ts\":0,\n        \"last_completed_signal_close_ts\":0,\n        \"managed\":False,\n        \"managed_signal_close_ts\":0,\n        \"entry_at_ms\":0,\n        \"entry_price\":0.0,\n        \"position_qty_eth\":0.0,\n        \"tp_trigger_price\":0.0,\n        \"tp_created\":False,\n        \"adverse_alerted\":False,\n        \"hold_alerted\":False,\n        \"stats\":{\n            \"entry_attempts\":0,\"entries_verified\":0,\"tp_created\":0,\n            \"completed_or_manual_exits\":0,\"rollbacks\":0,\n            \"alerts_1_5\":0,\"alerts_60m\":0\n        }\n    }\n\ndef load_state():\n    s=load_json(STATE)\n    return s if isinstance(s,dict) else default_state()\n\ndef lock_execution(reason):\n    try:\n        cfg=load_json(CONFIG,{})\n        cfg[\"live_enabled\"]=False\n        cfg[\"mode\"]=\"LOCKED\"\n        save_json(CONFIG,cfg)\n    except Exception: pass\n    try:\n        STOP.write_text(\"EXECUTION LOCKED: \"+str(reason)+\"\\n\",encoding=\"utf-8\")\n        os.chmod(STOP,0o600)\n    except Exception: pass\n\ndef live_gate(cfg):\n    return bool(cfg.get(\"live_enabled\")) and not STOP.exists()\n\ndef validate(vals,cfg):\n    if vals.get(\"LIGHTER_BASE_URL\")!=\"https://mainnet.zklighter.elliot.ai\":\n        raise RuntimeError(\"wrong base url\")\n    if int(vals.get(\"LIGHTER_ACCOUNT_INDEX\") or 0)!=ACCOUNT_INDEX:\n        raise RuntimeError(\"wrong account\")\n    if int(vals.get(\"LIGHTER_API_KEY_INDEX\") or -1)!=API_KEY_INDEX:\n        raise RuntimeError(\"wrong api key index\")\n    if not vals.get(\"LIGHTER_API_PRIVATE_KEY_HEX\"):\n        raise RuntimeError(\"private key missing\")\n    if int(cfg.get(\"account_index\") or 0)!=ACCOUNT_INDEX:\n        raise RuntimeError(\"config account mismatch\")\n    if int(cfg.get(\"api_key_index\") or -1)!=API_KEY_INDEX:\n        raise RuntimeError(\"config key mismatch\")\n    if int(cfg.get(\"market_index\") or -1)!=MARKET_INDEX:\n        raise RuntimeError(\"market mismatch\")\n    if abs(float(cfg.get(\"entry_size_eth\") or 0)-0.1)>1e-12:\n        raise RuntimeError(\"entry size must be 0.1\")\n    if float(cfg.get(\"hard_max_short_eth\") or 0)>HARD_MAX_ETH+1e-12:\n        raise RuntimeError(\"hard max exceeds 0.1\")\n    if cfg.get(\"allow_averaging\") is not False:\n        raise RuntimeError(\"averaging must be disabled\")\n    if cfg.get(\"spot_actions_allowed\") is not False:\n        raise RuntimeError(\"spot actions must be disabled\")\n    if cfg.get(\"auto_stop_loss\") is not False:\n        raise RuntimeError(\"auto stop loss must be disabled\")\n    if cfg.get(\"auto_timeout_exit\") is not False:\n        raise RuntimeError(\"auto timeout exit must be disabled\")\n\ndef public_account(vals):\n    url=vals[\"LIGHTER_BASE_URL\"].rstrip(\"/\")+\"/api/v1/account?\"+urllib.parse.urlencode({\n        \"by\":\"index\",\"value\":str(ACCOUNT_INDEX),\"active_only\":\"false\"\n    })\n    req=urllib.request.Request(url,headers={\"User-Agent\":\"eth-hedge-executor/1.0\"})\n    with urllib.request.urlopen(req,timeout=15) as r:\n        j=json.load(r)\n    a=(j.get(\"accounts\") or [{}])[0]\n    positions=[]\n    for p in a.get(\"positions\") or []:\n        try:q=abs(float(p.get(\"position\") or 0))\n        except Exception:q=0.0\n        if q<=1e-12: continue\n        raw_mid=p.get(\"market_id\")\n        if raw_mid is None: raw_mid=p.get(\"market_index\",-1)\n        positions.append({\n            \"market_id\":int(raw_mid),\n            \"symbol\":p.get(\"symbol\"),\n            \"sign\":int(p.get(\"sign\") or 0),\n            \"qty\":q,\n            \"avg_entry_price\":float(p.get(\"avg_entry_price\") or 0),\n            \"liquidation_price\":float(p.get(\"liquidation_price\") or 0),\n            \"unrealized_pnl\":float(p.get(\"unrealized_pnl\") or 0),\n        })\n    return {\n        \"available_balance\":float(a.get(\"available_balance\") or 0),\n        \"collateral\":float(a.get(\"collateral\") or 0),\n        \"positions\":positions\n    }\n\ndef classify(acct):\n    eth=None; other=[]\n    for p in acct[\"positions\"]:\n        if p[\"market_id\"]==MARKET_INDEX:\n            eth=p\n        else:\n            other.append(p)\n    return eth,other\n\ndef eth_units(qty):\n    units=int(round(float(qty)*BASE_SCALE))\n    if units<=0 or units>1000:\n        raise RuntimeError(\"base amount violates 0.1 ETH cap\")\n    return units\n\ndef price_i(px):\n    return int(round(float(px)*PRICE_SCALE))\n\ndef latest_price():\n    req=urllib.request.Request(BINANCE,headers={\"User-Agent\":\"eth-hedge-executor/1.0\"})\n    with urllib.request.urlopen(req,timeout=10) as r:\n        return float(json.load(r)[\"price\"])\n\nasync def get_client(vals):\n    from lighter import SignerClient\n    c=SignerClient(\n        vals[\"LIGHTER_BASE_URL\"],\n        ACCOUNT_INDEX,\n        {API_KEY_INDEX:vals[\"LIGHTER_API_PRIVATE_KEY_HEX\"]},\n    )\n    err=c.check_client()\n    if err is not None:\n        await c.close()\n        raise RuntimeError(\"signer check failed\")\n    return c\n\nasync def cancel_eth_orders(vals):\n    c=await get_client(vals)\n    try:\n        tx,resp,err=await c.cancel_all_orders(\n            time_in_force=c.CANCEL_ALL_TIF_IMMEDIATE,\n            timestamp_ms=0,\n            cancel_all_market_index=MARKET_INDEX,\n            api_key_index=API_KEY_INDEX,\n        )\n        if err is not None:\n            raise RuntimeError(\"cancel all failed: \"+str(err))\n        emit(\"CANCEL_ETH_ORDERS\")\n    finally:\n        await c.close()\n\nasync def send_short(vals,cfg,signal_ts):\n    c=await get_client(vals)\n    try:\n        idx=int(time.time()*1000)%2000000000\n        tx,resp,err=await c.create_market_order_if_slippage(\n            market_index=MARKET_INDEX,\n            client_order_index=idx,\n            base_amount=1000,\n            max_slippage=float(cfg[\"entry_max_slippage\"]),\n            is_ask=True,\n            reduce_only=False,\n            api_key_index=API_KEY_INDEX,\n        )\n        if err is not None:\n            raise RuntimeError(\"entry rejected: \"+str(err))\n        emit(\"ENTRY_SENT\",client_order_index=idx,signal_close_ts=signal_ts,qty_eth=0.1)\n    finally:\n        await c.close()\n\nasync def place_tp(vals,cfg,qty,entry):\n    units=eth_units(qty)\n    trigger=entry*(1-float(cfg[\"tp_pct\"]))\n    worst=trigger*(1+float(cfg[\"tp_max_slippage\"]))\n    c=await get_client(vals)\n    try:\n        idx=(int(time.time()*1000)+1)%2000000000\n        tx,resp,err=await c.create_tp_order(\n            market_index=MARKET_INDEX,\n            client_order_index=idx,\n            base_amount=units,\n            trigger_price=price_i(trigger),\n            price=price_i(worst),\n            is_ask=False,\n            reduce_only=True,\n            api_key_index=API_KEY_INDEX,\n        )\n        if err is not None:\n            raise RuntimeError(\"tp rejected: \"+str(err))\n        emit(\"TP_CREATED\",client_order_index=idx,qty_eth=qty,trigger_price=trigger,worst_price=worst)\n        return trigger\n    finally:\n        await c.close()\n\nasync def rollback_close(vals,cfg,qty,reason):\n    emit(\"ROLLBACK_BEGIN\",reason=reason,qty_eth=qty)\n    c=await get_client(vals)\n    try:\n        idx=(int(time.time()*1000)+2)%2000000000\n        tx,resp,err=await c.create_market_order_if_slippage(\n            market_index=MARKET_INDEX,\n            client_order_index=idx,\n            base_amount=eth_units(qty),\n            max_slippage=float(cfg[\"rollback_max_slippage\"]),\n            is_ask=False,\n            reduce_only=True,\n            api_key_index=API_KEY_INDEX,\n        )\n        if err is not None:\n            raise RuntimeError(\"rollback close rejected: \"+str(err))\n        emit(\"ROLLBACK_CLOSE_SENT\",client_order_index=idx,qty_eth=qty)\n    finally:\n        await c.close()\n\nasync def verify_short(vals):\n    for _ in range(20):\n        await asyncio.sleep(0.5)\n        acct=public_account(vals); eth,other=classify(acct)\n        if other:\n            raise RuntimeError(\"non-ETH exposure appeared\")\n        if eth:\n            if eth[\"sign\"]!=-1:\n                raise RuntimeError(\"ETH long/wrong sign appeared\")\n            if eth[\"qty\"]>0.10005:\n                raise RuntimeError(\"ETH short exceeds hard cap\")\n            return eth\n    raise RuntimeError(\"entry not verified\")\n\nasync def verify_flat(vals):\n    for _ in range(20):\n        await asyncio.sleep(0.5)\n        acct=public_account(vals); eth,other=classify(acct)\n        if not eth and not other:\n            return True\n    return False\n\nasync def tick():\n    with LOCK.open(\"a+\") as lf:\n        fcntl.flock(lf,fcntl.LOCK_EX)\n        vals=load_env(); cfg=load_json(CONFIG,{})\n        validate(vals,cfg)\n        s=load_state()\n        acct=public_account(vals)\n        eth,other=classify(acct)\n\n        if other:\n            lock_execution(\"non-ETH position detected\")\n            emit(\"SAFETY_LOCK\",reason=\"non-ETH position\",positions=other)\n            return 2\n        if eth and eth[\"sign\"]!=-1:\n            lock_execution(\"ETH long detected\")\n            emit(\"SAFETY_LOCK\",reason=\"ETH long detected\",position=eth)\n            return 2\n        if eth and eth[\"qty\"]>0.10005:\n            lock_execution(\"short cap exceeded\")\n            emit(\"SAFETY_LOCK\",reason=\"short cap exceeded\",position=eth)\n            return 2\n\n        # Locked mode is read-only by construction.\n        if not live_gate(cfg):\n            emit(\"LOCKED_TICK\",balance=acct[\"available_balance\"],collateral=acct[\"collateral\"],position=eth)\n            return 0\n\n        # Existing short must belong to this executor; never adopt or add to an external/manual short.\n        if eth:\n            if not s.get(\"managed\"):\n                lock_execution(\"unmanaged short detected\")\n                emit(\"SAFETY_LOCK\",reason=\"unmanaged short detected\",position=eth)\n                return 2\n            # Alert-only logic: never auto-exit at +1.5% or 60 minutes.\n            entry=float(s.get(\"entry_price\") or eth.get(\"avg_entry_price\") or 0)\n            if entry>0:\n                px=latest_price()\n                if not s.get(\"adverse_alerted\") and px>=entry*(1+float(cfg[\"adverse_alert_pct\"])):\n                    s[\"adverse_alerted\"]=True\n                    s[\"stats\"][\"alerts_1_5\"]+=1\n                    emit(\"ADVERSE_1_5_ALERT_ONLY\",entry_price=entry,observed_price=px,auto_exit=False)\n                if not s.get(\"hold_alerted\") and now_ms()-int(s.get(\"entry_at_ms\") or 0)>=int(cfg[\"hold_alert_minutes\"])*60*1000:\n                    s[\"hold_alerted\"]=True\n                    s[\"stats\"][\"alerts_60m\"]+=1\n                    emit(\"HOLD_60M_ALERT_ONLY\",entry_price=entry,auto_exit=False)\n                save_json(STATE,s)\n            return 0\n\n        # Flat after a managed trade means TP/manual/external close. Do not re-enter same signal.\n        if s.get(\"managed\"):\n            try:\n                await cancel_eth_orders(vals)\n            except Exception as ex:\n                emit(\"CANCEL_AFTER_FLAT_FAILED\",error=str(ex)[:300])\n            completed=int(s.get(\"managed_signal_close_ts\") or 0)\n            s[\"last_completed_signal_close_ts\"]=max(int(s.get(\"last_completed_signal_close_ts\") or 0),completed)\n            s[\"managed\"]=False\n            s[\"managed_signal_close_ts\"]=0\n            s[\"entry_at_ms\"]=0\n            s[\"entry_price\"]=0.0\n            s[\"position_qty_eth\"]=0.0\n            s[\"tp_trigger_price\"]=0.0\n            s[\"tp_created\"]=False\n            s[\"adverse_alerted\"]=False\n            s[\"hold_alerted\"]=False\n            s[\"stats\"][\"completed_or_manual_exits\"]+=1\n            save_json(STATE,s)\n            emit(\"MANUAL_OR_TP_EXIT_DETECTED\",completed_signal_close_ts=completed)\n            return 0\n\n        mon=load_json(MONITOR_STATE,{})\n        sig=mon.get(\"active_signal\") if isinstance(mon,dict) else None\n        if not isinstance(sig,dict):\n            return 0\n        sig_ts=int(sig.get(\"signal_close_ts\") or 0)\n        if sig_ts<=0:\n            return 0\n        if sig_ts<=int(s.get(\"last_attempted_signal_close_ts\") or 0):\n            return 0\n        if sig_ts<=int(s.get(\"last_completed_signal_close_ts\") or 0):\n            return 0\n        lag=(now_ms()-sig_ts)/1000.0\n        if lag<0 or lag>float(cfg[\"max_signal_entry_lag_seconds\"]):\n            s[\"last_attempted_signal_close_ts\"]=sig_ts\n            save_json(STATE,s)\n            emit(\"SIGNAL_SKIPPED_STALE\",signal_close_ts=sig_ts,lag_seconds=round(lag,3))\n            return 0\n\n        # Final account recheck immediately before sending.\n        pre=public_account(vals); pre_eth,pre_other=classify(pre)\n        if pre_eth or pre_other:\n            emit(\"ENTRY_BLOCKED_NOT_FLAT\",positions=pre[\"positions\"])\n            return 0\n        if pre[\"collateral\"]<float(cfg[\"min_collateral_usdc\"]):\n            lock_execution(\"collateral below safety floor\")\n            emit(\"SAFETY_LOCK\",reason=\"low collateral\",collateral=pre[\"collateral\"])\n            return 2\n\n        # Exactly one entry attempt per signal.\n        s[\"last_attempted_signal_close_ts\"]=sig_ts\n        s[\"stats\"][\"entry_attempts\"]+=1\n        save_json(STATE,s)\n\n        try:\n            await send_short(vals,cfg,sig_ts)\n            pos=await verify_short(vals)\n            s[\"managed\"]=True\n            s[\"managed_signal_close_ts\"]=sig_ts\n            s[\"entry_at_ms\"]=now_ms()\n            s[\"entry_price\"]=float(pos[\"avg_entry_price\"])\n            s[\"position_qty_eth\"]=float(pos[\"qty\"])\n            s[\"adverse_alerted\"]=False\n            s[\"hold_alerted\"]=False\n            s[\"stats\"][\"entries_verified\"]+=1\n            save_json(STATE,s)\n            try:\n                trigger=await place_tp(vals,cfg,pos[\"qty\"],pos[\"avg_entry_price\"])\n                s[\"tp_trigger_price\"]=trigger\n                s[\"tp_created\"]=True\n                s[\"stats\"][\"tp_created\"]+=1\n                save_json(STATE,s)\n                emit(\"ENTRY_AND_TP_READY\",signal_close_ts=sig_ts,entry_price=pos[\"avg_entry_price\"],qty_eth=pos[\"qty\"],tp_trigger_price=trigger,liquidation_price=pos[\"liquidation_price\"])\n            except Exception as tp_ex:\n                s[\"stats\"][\"rollbacks\"]+=1\n                save_json(STATE,s)\n                emit(\"TP_SETUP_FAILED\",error=str(tp_ex)[:500])\n                try:\n                    await rollback_close(vals,cfg,pos[\"qty\"],\"tp setup failed\")\n                    flat=await verify_flat(vals)\n                except Exception as rb_ex:\n                    flat=False\n                    emit(\"ROLLBACK_FAILED\",error=str(rb_ex)[:500])\n                lock_execution(\"TP setup failed; execution locked\")\n                if flat:\n                    s[\"managed\"]=False\n                    s[\"last_completed_signal_close_ts\"]=sig_ts\n                    save_json(STATE,s)\n                    emit(\"ROLLBACK_VERIFIED_FLAT\")\n                return 2\n        except Exception as ex:\n            lock_execution(\"entry execution error\")\n            emit(\"ENTRY_ERROR_LOCKED\",error=str(ex)[:500])\n            return 2\n        return 0\n\ndef status():\n    vals=load_env(); cfg=load_json(CONFIG,{})\n    validate(vals,cfg)\n    acct=public_account(vals); eth,other=classify(acct)\n    print(json.dumps({\n        \"account_index\":ACCOUNT_INDEX,\n        \"api_key_index\":API_KEY_INDEX,\n        \"mode\":cfg.get(\"mode\"),\n        \"live_enabled\":bool(cfg.get(\"live_enabled\")),\n        \"stop_execution\":STOP.exists(),\n        \"live_gate\":live_gate(cfg),\n        \"entry_size_eth\":cfg.get(\"entry_size_eth\"),\n        \"hard_max_short_eth\":cfg.get(\"hard_max_short_eth\"),\n        \"tp_pct\":cfg.get(\"tp_pct\"),\n        \"auto_stop_loss\":cfg.get(\"auto_stop_loss\"),\n        \"auto_timeout_exit\":cfg.get(\"auto_timeout_exit\"),\n        \"allow_averaging\":cfg.get(\"allow_averaging\"),\n        \"spot_actions_allowed\":cfg.get(\"spot_actions_allowed\"),\n        \"account\":acct,\n        \"state\":load_state(),\n        \"monitor_active_signal\":(load_json(MONITOR_STATE,{}) or {}).get(\"active_signal\"),\n    },ensure_ascii=False,indent=2))\n\nif __name__==\"__main__\":\n    ap=argparse.ArgumentParser()\n    ap.add_argument(\"--status\",action=\"store_true\")\n    a=ap.parse_args()\n    if a.status: status()\n    else: raise SystemExit(asyncio.run(tick()))\n",encoding="utf-8");os.chmod(EXE,0o700)
ADM.write_text("#!/usr/bin/env python3\nimport argparse, json, os, pathlib, urllib.parse, urllib.request\nROOT=pathlib.Path(\"/home/apr/eth-hedge-live\")\nCFG=ROOT/\"executor_config.json\"\nSTOP=ROOT/\"STOP_EXECUTION\"\n\ndef save(c):\n    t=CFG.with_suffix(\".tmp\")\n    t.write_text(json.dumps(c,ensure_ascii=False,indent=2)+\"\\n\")\n    os.replace(t,CFG); os.chmod(CFG,0o600)\n\ndef account_flat():\n    url=\"https://mainnet.zklighter.elliot.ai/api/v1/account?\"+urllib.parse.urlencode({\"by\":\"index\",\"value\":\"749122\",\"active_only\":\"false\"})\n    req=urllib.request.Request(url,headers={\"User-Agent\":\"eth-hedge-admin/1.0\"})\n    with urllib.request.urlopen(req,timeout=15) as r:j=json.load(r)\n    a=(j.get(\"accounts\") or [{}])[0]\n    pos=[]\n    for p in a.get(\"positions\") or []:\n        try:q=float(p.get(\"position\") or 0)\n        except:q=0\n        if abs(q)>1e-12:pos.append(p)\n    return len(pos)==0,float(a.get(\"collateral\") or 0)\n\nap=argparse.ArgumentParser()\nap.add_argument(\"action\",choices=[\"status\",\"enable\",\"disable\"])\nap.add_argument(\"--confirm\",default=\"\")\na=ap.parse_args()\ncfg=json.loads(CFG.read_text())\nif a.action==\"status\":\n    print(json.dumps({\"live_enabled\":cfg.get(\"live_enabled\"),\"mode\":cfg.get(\"mode\"),\"stop_execution\":STOP.exists()},indent=2))\nelif a.action==\"disable\":\n    cfg[\"live_enabled\"]=False;cfg[\"mode\"]=\"LOCKED\";save(cfg)\n    STOP.write_text(\"EXECUTION LOCKED by user\\n\");os.chmod(STOP,0o600)\n    print(\"EXECUTION_LOCKED\")\nelse:\n    if a.confirm!=\"ENABLE-749122-0.1ETH\":\n        raise SystemExit(\"confirmation phrase required\")\n    flat,col=account_flat()\n    if not flat: raise SystemExit(\"refusing enable: account is not flat\")\n    if col<80: raise SystemExit(\"refusing enable: collateral below 80 USDC\")\n    if int(cfg.get(\"account_index\") or 0)!=749122 or int(cfg.get(\"api_key_index\") or -1)!=45:\n        raise SystemExit(\"refusing enable: identity mismatch\")\n    if float(cfg.get(\"hard_max_short_eth\") or 0)>0.1 or cfg.get(\"allow_averaging\") is not False:\n        raise SystemExit(\"refusing enable: risk guardrail mismatch\")\n    cfg[\"live_enabled\"]=True;cfg[\"mode\"]=\"LIVE\";save(cfg)\n    if STOP.exists():STOP.unlink()\n    print(\"EXECUTION_ENABLED\")\n    print(\"account_index = 749122\")\n    print(\"max_short_eth = 0.1\")\n    print(\"note = no immediate order; future valid signal only\")\n",encoding="utf-8");os.chmod(ADM,0o700)
